auto func (auto value){  
    int max_val = value[0];
    int sum = 0;
    for(auto elem : value){
        if(elem > max_val) max_val = elem;
        sum += elem;
    }
    return std::make_tuple(max_val, sum, static_cast<double>(sum)/value.size());
